import{At as e,mt as t,n,pt as r}from"./chunks/framework.BrKcMR_c.js";var i=JSON.parse(`{"title":"ADR-0018: Monorepo layout + GitHub build/release tooling","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0018-monorepo-and-github-tooling.md","filePath":"adrs/0018-monorepo-and-github-tooling.md","lastUpdated":1789092097000}`),a={name:`adrs/0018-monorepo-and-github-tooling.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0018-monorepo-layout-github-build-release-tooling" tabindex="-1">ADR-0018: Monorepo layout + GitHub build/release tooling <a class="header-anchor" href="#adr-0018-monorepo-layout-github-build-release-tooling" aria-label="Permalink to “ADR-0018: Monorepo layout + GitHub build/release tooling”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-08-30 · <code>web/</code> refined by <a href="/adrs/0041-website-as-vite-vue-spa">ADR-0041</a></p><p>The layout decision remains current. The original publication plan below is superseded by <a href="/adrs/0040-single-source-release-identity">ADR-0040</a> and <a href="/adrs/0078-owner-approved-release-signing">ADR-0078</a>: the public preview has source and documentation, Pages publication is manual, and official downloads require signing and notarization. App CI now uses macOS 26. Private planning is excluded from the public tree. Follow <a href="/Releasing">Releasing</a> for the current procedure.</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>GOAT is going open source. A single flat repo mixing the Swift app, docs, and a marketing/site directory would tangle three audiences (users, contributors, the curious) and three release cadences. We also need reproducible builds, downloadable releases, browsable docs, and a public face, none of which existed.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p><strong>Monorepo, three top-level areas:</strong></p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark-dimmed" style="--shiki-light:#24292e;--shiki-dark:#adbac7;--shiki-light-bg:#fff;--shiki-dark-bg:#22272e;" tabindex="0" dir="ltr"><code><span class="line"><span>apps/goat-macos/   # the app (App/ + Packages/ + project.yml + Makefile + art/)</span></span>
<span class="line"><span>web/               # the GitHub Pages landing site (Vite + Vue SPA since ADR-0041)</span></span>
<span class="line"><span>docs/              # shared docs: PLAN, DESIGN, ENGINES, ADRs, wiki/ source</span></span>
<span class="line"><span>.github/           # CI + release workflows, issue/PR templates, community health</span></span>
<span class="line"><span>assets/            # shared brand images</span></span></code></pre></div><p><code>make</code> targets run from the repo root and delegate into <code>apps/goat-macos</code>, so developer muscle memory (<code>make build</code>, <code>make verify</code>) is unchanged.</p><p><strong>GitHub tooling:</strong></p><ul><li><strong>CI</strong> (<code>ci.yml</code>): swift-format lint (needs no SDK) + package/app build &amp; tests on push and PR.</li><li><strong>Release</strong> (<code>release.yml</code>): tag <code>v*</code> → Release build with Hardened Runtime → DMG (pure <code>hdiutil</code>, no extra deps) → optional notarization (skipped unless Apple secrets are set) → checksums → a <strong>draft</strong> GitHub Release. Signing is <strong>ad-hoc by default, notarize-ready</strong>: the full Developer ID path is wired but gated on secrets, so the project ships usable binaries today and Gatekeeper-clean ones the moment credentials exist ([ADR-0007] governs the runtime).</li><li><strong>Pages</strong> (<code>pages.yml</code>): deploys <code>web/</code> on change.</li><li><strong>Docs</strong> live three ways by nature: <strong>ADRs/PLAN</strong> in-repo for contributors, the <strong>wiki</strong> (source in <code>docs/wiki/</code>) for users, <strong>Issues/Discussions</strong> for the conversation.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><p>Clean separation with no DX regression. Binaries are downloadable from day one; notarization is a secrets-only upgrade. One real constraint: GOAT targets macOS 26, and GitHub-hosted runners may lag. Workflows pin <code>macos-15</code> with a one-line bump point, or a self-hosted Xcode-26 runner. Placeholder <code>OWNER/REPO</code> strings in the site and docs are the only things that need filling in after the repo is created.</p><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p>Separate repos per concern (rejected: coordination tax, atomic cross-cutting changes become multi-PR); app at repo root with site on a <code>gh-pages</code> branch (rejected: branch-as-directory is harder to reason about than <code>web/</code>); Fastlane for release (rejected: a 30-line script + <code>hdiutil</code> covers it without the dependency); notarized-only releases (rejected: blocks all binaries behind a paid account before the project has users).</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};